package e.e.a;
import android.view.*;import android.preference.*;import org.junit.*;import static org.junit.Assert.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={28,34,36},manifest=Config.NONE)
public class Timeline218Test {
 AppliedApkTest.Screen a;View root,status,controller,frame;
 @Before public void setup()throws Exception{new AppliedApkTest().prepare();a=Robolectric.buildActivity(AppliedApkTest.Screen.class).setup().get();a.setTheme(0x7f1000a2);AppliedApkTest.apkResources.getConfiguration().orientation=1;PreferenceManager.getDefaultSharedPreferences(a).edit().clear().putString("player_controls_visibility_mode","off").commit();root=LayoutInflater.from(a).inflate(0x7f0b0061,null);((ViewGroup)a.getWindow().getDecorView().findViewById(android.R.id.content)).addView(root);controller=PortraitTimeline213.find(root,"controller");status=PortraitTimeline213.find(root,"statuslay");frame=PortraitTimeline213.find(root,"videoLayout");System.out.println("timeline original parent="+a.getResources().getResourceEntryName(((View)controller.getParent()).getId()));}
 @After public void cleanup(){PortraitTimeline213.restore(root);a.finish();AppliedApkTest.apkResources=null;}
 @Test public void normalTimelineRemainsAtVideoBottomAfterLayout(){PortraitTimeline213.update(root);for(int i=0;i<3;i++){root.measure(View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY));root.layout(0,0,1080,1920);}int[] bar=new int[2],video=new int[2];controller.getLocationOnScreen(bar);frame.getLocationOnScreen(video);assertTrue(controller.getHeight()>0);assertEquals(video[1]+frame.getHeight(),bar[1]+controller.getHeight());}
 @Test public void detachAndRestorePreserveOriginalHierarchy(){ViewParent original=controller.getParent();PortraitTimeline213.update(root);PortraitTimeline213.restore(root);assertSame(original,controller.getParent());PortraitTimeline213.update(root);status.setVisibility(View.INVISIBLE);assertFalse(controller.isShown());}
 @Test public void normalTimelineFollowsNativeAutoHide(){PortraitTimeline213.update(root);status.setVisibility(View.INVISIBLE);assertFalse("Timeline escaped native auto-hide container",controller.isShown());status.setVisibility(View.VISIBLE);assertTrue(controller.isShown());}
 @Test public void explicitlyHeldControlsStayVisible(){PreferenceManager.getDefaultSharedPreferences(a).edit().putString("player_controls_visibility_mode","normal").commit();PortraitTimeline213.update(root);status.setVisibility(View.INVISIBLE);assertTrue(controller.isShown());}
 @Test public void visibilitySettingCanChangeWithoutRecreatingPlayer(){PortraitTimeline213.update(root);PreferenceManager.getDefaultSharedPreferences(a).edit().putString("player_controls_visibility_mode","normal").commit();PortraitTimeline213.update(root);status.setVisibility(View.INVISIBLE);assertTrue(controller.isShown());PreferenceManager.getDefaultSharedPreferences(a).edit().putString("player_controls_visibility_mode","off").commit();PortraitTimeline213.update(root);assertFalse(controller.isShown());}
}
